<?php
require_once __DIR__.'/includes/functions.php';require_login();$pageTitle='Feedback — DriveEase';$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$title=trim($_POST['title']??'');$type=$_POST['feedback_type']??'General';$desc=trim($_POST['description']??'');if($title==='')$errors[]='Feedback title is required.';if(!in_array($type,['General','Suggestion','Complaint','Compliment'],true))$errors[]='Choose a valid feedback type.';if(mb_strlen($desc)<5)$errors[]='Please write at least 5 characters.';if(!$errors){$s=db()->prepare('INSERT INTO feedback (customer_id,title,feedback_type,description) VALUES (?,?,?,?)');$s->execute([current_user()['id'],$title,$type,$desc]);log_activity('Submitted feedback');flash('success','Thanks — your feedback has been submitted.');redirect('feedback.php');}}
$s=db()->prepare('SELECT * FROM feedback WHERE customer_id=? ORDER BY created_at DESC');$s->execute([current_user()['id']]);$items=$s->fetchAll();require __DIR__.'/includes/header.php'; ?>
<section class="page-hero page-hero-compact"><div class="container"><span class="eyebrow">WE'RE LISTENING</span><h1>Feedback that <span class="text-gradient">moves us forward.</span></h1><p>Share a suggestion, compliment, or concern with our team.</p></div></section><section class="section"><div class="container content-narrow"><div class="panel form-panel"><h2>Share your feedback</h2><?php if($errors): ?><div class="alert alert-danger"><ul><?php foreach($errors as $er): ?><li><?= e($er) ?></li><?php endforeach; ?></ul></div><?php endif; ?><form method="post" class="form-stack"><?= csrf_field() ?><label>Title<input required name="title" maxlength="180" value="<?= e($_POST['title']??'') ?>"></label><label>Feedback type<select name="feedback_type"><option>General</option><option>Suggestion</option><option>Complaint</option><option>Compliment</option></select></label><label>Your message<textarea required name="description" rows="5" minlength="5"><?= e($_POST['description']??'') ?></textarea></label><button class="btn btn-primary">Submit feedback ↗</button></form></div><div class="section-heading"><div><span class="eyebrow">YOUR VOICE</span><h2>Previous feedback</h2></div></div><?php foreach($items as $item): ?><article class="feedback-card"><div class="feedback-card-head"><div><h3><?= e($item['title']) ?></h3><small><?= e($item['feedback_type']) ?> · <?= e($item['created_at']) ?></small></div><span class="status status-<?= $item['staff_reply']?'replied':'pending' ?>"><?= $item['staff_reply']?'Replied':'Awaiting reply' ?></span></div><p><?= nl2br(e($item['description'])) ?></p><?php if($item['staff_reply']): ?><div class="reply-note"><b>Team reply</b><p><?= nl2br(e($item['staff_reply'])) ?></p></div><?php endif; ?></article><?php endforeach; ?></div></section>
